-- PDCA Compliance · /dashboard/ehs/setores (aud8 90/95) · RD-95: "?" (AjudaCampo) em colunas, busca e abas.
-- ADITIVA: só textos de ajuda novos (erp_ajuda_campo). Não cria/altera tabela, RLS, policy, grant ou dado de cliente.
-- Idempotente (ON CONFLICT (chave) DO NOTHING).
INSERT INTO public.erp_ajuda_campo (chave, grupo, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum, ordem, rota, vertical, status)
SELECT v.chave, v.grupo, v.rotulo, v.o_que, v.para_que, v.exemplo, v.erro, v.ordem, v.rota, 'compliance', 'publicado'
FROM (VALUES
 ('compliance.setores.aba_globais', 'Setores', 'Globais (PS)', 'Nada a preencher: é o catálogo de setores padrão da PS Gestão, só leitura.', 'Dá um ponto de partida pronto (Administrativo, Produção, Manutenção…) sem você cadastrar do zero; disponível para todas as empresas.', 'Usar "Produção" do catálogo global em vez de criar um setor novo igual.', 'Tentar editar um setor global: para ajustar, crie o seu em "Meus setores".', 1, '/dashboard/ehs/setores'),
 ('compliance.setores.aba_meus', 'Setores', 'Meus setores', 'Nada a preencher: mostra os setores que a sua empresa criou (com Editar e Desativar).', 'Separa o que é seu do catálogo global; é aqui que você cria, edita e desativa setores da empresa.', 'Criar "Expedição" quando o catálogo global não tem esse setor.', 'Procurar um setor recém-criado na aba Globais: ele fica em Meus setores.', 2, '/dashboard/ehs/setores'),
 ('compliance.setores.busca', 'Setores', 'Buscar', 'Digite parte do nome ou da descrição do setor para filtrar a lista.', 'Encontra rápido um setor numa lista grande, sem rolar a tabela toda.', 'Digitar "manut" para achar "Manutenção".', 'Esperar que a busca procure por outras empresas: a lista só traz os setores da sua.', 3, '/dashboard/ehs/setores'),
 ('compliance.setores.nome', 'Setores', 'Nome', 'O nome do setor de trabalho como as pessoas o conhecem na empresa.', 'É por ele que você liga funcionários, EPIs e documentos de SST ao setor; aparece em relatórios e no PGR.', 'Produção, Administrativo, Almoxarifado.', 'Repetir o mesmo setor com grafias diferentes ("Produção" e "producao"): dificulta somar os dados.', 4, '/dashboard/ehs/setores'),
 ('compliance.setores.slug', 'Setores', 'Slug', 'Nada a preencher: é o identificador curto gerado a partir do nome (sem espaços nem acentos).', 'Serve de chave estável para integrações e para o sistema não confundir setores de nome parecido.', 'O setor "Manutenção" vira o slug "manutencao".', 'Tentar editar o slug à mão: ele é derivado do nome automaticamente.', 5, '/dashboard/ehs/setores'),
 ('compliance.setores.descricao', 'Setores', 'Descrição', 'Um texto curto explicando o que o setor faz ou abrange (opcional).', 'Ajuda quem for classificar funcionários a escolher o setor certo; aparece ao lado do nome.', 'Em "Manutenção": "Manutenção elétrica e mecânica da fábrica".', 'Deixar a descrição genérica demais a ponto de não diferenciar dois setores parecidos.', 6, '/dashboard/ehs/setores'),
 ('compliance.setores.empresa', 'Setores', 'Empresa', 'Nada a preencher: mostra a qual empresa do grupo o setor pertence.', 'Quando você vê mais de uma empresa, deixa claro de quem é cada setor para não misturar as carteiras.', 'O setor "Obra 1" aparece com a empresa "Construtora Alfa".', 'Criar o setor na empresa errada: confira a "Empresa-alvo" antes de salvar.', 7, '/dashboard/ehs/setores'),
 ('compliance.setores.acoes', 'Setores', 'Ações', 'Nada a preencher: os botões para Editar ou Desativar o setor.', 'Editar ajusta nome/descrição; Desativar esconde o setor sem apagar o histórico (soft delete) de quem já estava ligado a ele.', 'Desativar "Expedição" quando o setor deixou de existir, mantendo os registros antigos.', 'Desativar um setor em uso achando que ele some dos relatórios passados: o histórico é preservado.', 8, '/dashboard/ehs/setores')
) AS v(chave, grupo, rotulo, o_que, para_que, exemplo, erro, ordem, rota)
WHERE EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'erp_ajuda_campo')
ON CONFLICT (chave) DO NOTHING;
